=SUMIFS(D:D, B:B, "Nord", C:C, ">="&DATE(2026,1,1))
=SOMMA.PIÙ.SE(D:D; B:B; "Nord"; C:C; ">="&DATA(2026;1;1))       (italiano)

=COUNTIFS(E:E, "pagato")          quanti ordini pagati', 'text'),
            P('Le funzioni si possono annidare (`=ROUND(AVERAGE(B2:B10), 1)`). Se compare un errore: `#DIV/0!` divisione per zero, `#N/D` valore non trovato, `#NOME?` nome di funzione sbagliato (spesso perché hai usato il nome inglese nell’Excel italiano; in inglese gli errori si chiamano `#N/A` e `#NAME?`). `IFERROR`/`SE.ERRORE` sostituisce l’errore con un valore.', 'Functions can be nested (`=ROUND(AVERAGE(B2:B10), 1)`). If an error shows: `#DIV/0!` division by zero, `#N/A` value not found, `#NAME?` wrong function name (often because you used the English name in Italian Excel). `IFERROR`/`SE.ERRORE` replaces the error with a value.'),
        ], [
            Q('n1', L('Che cosa fa `SE` / `IF`?', 'What does `IF` / `SE` do?'), [L('Restituisce un valore o un altro secondo una condizione', 'Returns one value or another based on a condition'), L('Somma una colonna', 'Sums a column'), L('Ordina i dati', 'Sorts data'), L('Crea un grafico', 'Creates a chart')], 0, L('Condizione, se vero, se falso.', 'Condition, if true, if false.')),
            Q('n2', L('Quale funzione somma solo le righe che rispettano dei criteri?', 'Which function sums only rows meeting criteria?'), ['SUMIFS / SOMMA.PIÙ.SE', 'SUM / SOMMA', 'COUNT / CONTA.NUMERI', 'MAX'], 0, L('Più criteri insieme.', 'Several criteria at once.')),
            Q('n3', L('Che cosa indica l’errore `#NOME?` (in inglese `#NAME?`)?', 'What does the `#NAME?` error mean?'), [L('Nome di funzione non riconosciuto', 'Function name not recognised'), L('Divisione per zero', 'Division by zero'), L('Valore non trovato', 'Value not found'), L('Foglio pieno', 'Sheet full')], 0, L('Spesso inglese nell’Excel italiano.', 'Often English names in Italian Excel.')),
        ], task('excel', L('Scrivi una formula che in F2 mostri `"Promosso"` se `E2` è maggiore o uguale a 18, altrimenti `"Rimandato"` (con `IF` e la virgola o `SE` e il punto e virgola).', 'Write a formula showing in F2 `"Promosso"` if `E2` is at least 18, otherwise `"Rimandato"` (with `IF` and commas or `SE` and semicolons).'), '', [re('^\s*=\s*(IF|SE)\s*\(\s*E2\s*>=\s*18\s*[,;]\s*"Promosso"\s*[,;]\s*"Rimandato"\s*\)\s*$', L('La condizione giusta', 'The right condition'))], '', '=SE(E2>=18; "Promosso"; "Rimandato")'), [
            dMatch(pMatch(), [['SUM', 'SOMMA'], ['AVERAGE', 'MEDIA'], ['IF', 'SE'], ['SUMIFS', 'SOMMA.PIÙ.SE'], ['IFERROR', 'SE.ERRORE']], L('Inglese e italiano.', 'English and Italian.')),
            dBug(pBug(), ['=MEDIA(B2:B10)', '=SOMMA(C2:C10)', '=SE(D2>100, "alto", "basso")'], 2, '=SE(D2>100; "alto"; "basso")', L('Nell’Excel italiano si separa con il punto e virgola.', 'In Italian Excel you separate with semicolons.')),
        ]),
        lesson('lookup', L('Cercare dati: CERCA.X', 'Looking up data: XLOOKUP'), [
            P('Per prendere un dato da un’altra tabella (il prezzo di un codice prodotto, il nome di un cliente) si usa **`XLOOKUP`** (in italiano **`CERCA.X`**): cerca un valore in una colonna e restituisce il valore corrispondente di un’altra. Sostituisce il vecchio `VLOOKUP`/`CERCA.VERT`, più fragile. È disponibile da Excel 2021 e in Microsoft 365.', 'To fetch data from another table (a product code’s price, a customer’s name) you use **`XLOOKUP`** (Italian **`CERCA.X`**): it looks up a value in one column and returns the matching value from another. It replaces the old, more fragile `VLOOKUP`/`CERCA.VERT`. It is available from Excel 2021 and in Microsoft 365.'),
            C('=XLOOKUP(A2, Listino!A:A, Listino!C:C, "non trovato")
=CERCA.X(A2; Listino!A:A; Listino!C:C; "non trovato")      (italiano)

    cerca il codice di A2 nella colonna A del foglio Listino
    e restituisce il prezzo dalla colonna C', 'text'),
            P('Rispetto a `CERCA.VERT`, `CERCA.X` cerca in qualsiasi direzione, non si rompe se inserisci colonne e cerca il valore esatto di base. Il quarto argomento evita l’errore `#N/D` quando il valore non c’è.', 'Compared to `VLOOKUP`, `XLOOKUP` searches in any direction, does not break if you insert columns and looks for the exact value by default. The fourth argument avoids the `#N/A` error when the value is missing.'),
        ], [
            Q('l1', L('Che cosa fa CERCA.X / XLOOKUP?', 'What does XLOOKUP / CERCA.X do?'), [L('Cerca un valore e restituisce il corrispondente di un’altra colonna', 'Looks up a value and returns the matching one from another column'), L('Ordina i dati', 'Sorts data'), L('Cancella i doppioni', 'Removes duplicates'), L('Crea una tabella pivot', 'Creates a pivot table')], 0, L('Come una piccola query.', 'Like a small query.')),
            Q('l2', L('Perché preferirlo a CERCA.VERT?', 'Why prefer it to VLOOKUP?'), [L('Non si rompe inserendo colonne e cerca in ogni direzione', 'It does not break on inserted columns and searches any direction'), L('È più vecchio', 'It is older'), L('Non c’è differenza', 'There is no difference'), L('Funziona solo su Mac', 'It only works on Mac')], 0, L('Più robusto.', 'More robust.')),
            Q('l3', L('A che cosa serve il quarto argomento?', 'What is the fourth argument for?'), [L('Il valore da mostrare se non trova niente', 'The value shown if nothing is found'), L('Il colore della cella', 'The cell colour'), L('Il numero di righe', 'The number of rows'), L('Il nome del foglio', 'The sheet name')], 0, L('Niente #N/D.', 'No #N/A.')),
        ], task('excel', L('Scrivi una formula `CERCA.X` (o `XLOOKUP`) che cerca il codice in `A2` nella colonna `Clienti!A:A` e restituisce l’email da `Clienti!D:D`, con `"assente"` se non lo trova.', 'Write an `XLOOKUP` (or `CERCA.X`) formula looking up the code in `A2` in column `Clienti!A:A` and returning the email from `Clienti!D:D`, with `"assente"` if not found.'), '', [re('^\s*=\s*(XLOOKUP|CERCA\.X)\s*\(\s*A2\s*[,;]\s*Clienti!A:A\s*[,;]\s*Clienti!D:D\s*[,;]\s*"assente"\s*\)\s*$', L('La ricerca completa', 'The complete lookup'))], '', '=CERCA.X(A2; Clienti!A:A; Clienti!D:D; "assente")'), [
            dOrder(pSort(), ['=CERCA.X(', 'A2;', 'Listino!A:A;', 'Listino!C:C;', '"non trovato")'], L('Cosa cerchi, dove, cosa restituire, se manca.', 'What you look for, where, what to return, if missing.')),
            dMatch(pMatch(), [['XLOOKUP', 'CERCA.X'], ['VLOOKUP', 'CERCA.VERT'], [L('#N/D', '#N/A'), L('Valore non trovato', 'Value not found')], ['Listino!A:A', L('Colonna di un altro foglio', 'Column on another sheet')]], L('Cercare tra tabelle.', 'Looking up across tables.')),
        ]),
        lesson('pivot', L('Tabelle, pivot e grafici', 'Tables, pivots and charts'), [
            P('Trasforma i dati in una **tabella** (Inserisci → Tabella, o Ctrl+T): ottieni filtri, righe colorate, totali e formule che si estendono da sole. Una regola d’oro: una riga per record, una colonna per campo, intestazioni chiare, niente celle unite.', 'Turn data into a **table** (Insert → Table, or Ctrl+T): you get filters, banded rows, totals and formulas that extend by themselves. A golden rule: one row per record, one column per field, clear headers, no merged cells.'),
            P('Una **tabella pivot** riassume migliaia di righe in pochi secondi: trascini i campi in Righe (es. Regione), Colonne (es. Anno) e Valori (es. somma delle Vendite) e Excel calcola i totali per ogni combinazione. Da una pivot si crea un **grafico pivot** che si aggiorna con i filtri.', 'A **pivot table** summarises thousands of rows in seconds: you drag fields into Rows (e.g. Region), Columns (e.g. Year) and Values (e.g. sum of Sales) and Excel computes totals for every combination. From a pivot you create a **pivot chart** that updates with the filters.'),
            Tip('Scegli il grafico in base alla domanda: barre per confrontare categorie, linee per l’andamento nel tempo, torta solo per poche parti di un totale.', 'Pick the chart by the question: bars to compare categories, lines for trends over time, pie only for a few parts of a whole.'),
        ], [
            Q('p1', L('Che cosa fa una tabella pivot?', 'What does a pivot table do?'), [L('Riassume i dati per categorie', 'Summarises data by categories'), L('Disegna immagini', 'Draws images'), L('Cancella righe', 'Deletes rows'), L('Invia email', 'Sends email')], 0, L('Righe, colonne, valori.', 'Rows, columns, values.')),
            Q('p2', L('Quale grafico per l’andamento nel tempo?', 'Which chart for trends over time?'), [L('A linee', 'Line'), L('A torta', 'Pie'), L('A dispersione 3D', '3D scatter'), L('Nessuno', 'None')], 0, L('Le barre confrontano categorie.', 'Bars compare categories.')),
            Q('p3', L('Che cosa evitare nei dati da analizzare?', 'What should you avoid in data to analyse?'), [L('Le celle unite', 'Merged cells'), L('Le intestazioni', 'Headers'), L('Una riga per record', 'One row per record'), L('I numeri', 'Numbers')], 0, L('Rompono filtri e pivot.', 'They break filters and pivots.')),
        ], task('text', L('Descrivi una tabella pivot per vedere le vendite totali per regione e anno, una riga per area come `Righe: …`, `Colonne: …`, `Valori: …`.', 'Describe a pivot table showing total sales by region and year, one line per area as `Rows: …`, `Columns: …`, `Values: …`.'), "Righe: \nColonne: \nValori: ", [re('^(Righe|Rows):\s*(Regione|Region)', L('Regione nelle righe', 'Region in rows')), re('^(Colonne|Columns):\s*(Anno|Year)', L('Anno nelle colonne', 'Year in columns')), re('^(Valori|Values):.*(Somma|Sum|Totale|Total).*(Vendite|Sales)|^(Valori|Values):.*(Vendite|Sales).*(somma|sum)', L('Somma delle vendite nei valori', 'Sum of sales in values'))], '', "Righe: Regione\nColonne: Anno\nValori: Somma di Vendite"), [
            dMatch(pMatch(), [['Ctrl+T', L('Crea una tabella', 'Creates a table')], [L('Pivot: Righe', 'Pivot: Rows'), L('Categorie verticali', 'Vertical categories')], [L('Pivot: Valori', 'Pivot: Values'), L('Cosa calcolare', 'What to compute')], [L('Grafico a barre', 'Bar chart'), L('Confrontare categorie', 'Compare categories')], [L('Grafico a linee', 'Line chart'), L('Andamento nel tempo', 'Trend over time')]], L('Dai dati alle risposte.', 'From data to answers.')),
            dFlash(pFlash(), [[L('Una tabella estende da sola le formule', 'A table extends formulas by itself'), true], [L('Le celle unite aiutano le tabelle pivot', 'Merged cells help pivot tables'), false], [L('Un grafico pivot si aggiorna con i filtri', 'A pivot chart updates with filters'), true], [L('La torta è ideale per 20 categorie', 'A pie is ideal for 20 categories'), false]], L('Riassumere e mostrare.', 'Summarise and show.')),
        ]),
        lesson('dynamic', L('Matrici dinamiche e funzioni logiche', 'Dynamic arrays and logical functions'), [
            P('Le **matrici dinamiche** restituiscono più risultati da una sola formula, che si “espandono” nelle celle vicine. `FILTRO` estrae le righe che rispettano una condizione, `ORDINA` le mette in ordine, `UNICI` toglie i doppioni.', '**Dynamic arrays** return many results from one formula, which “spill” into neighbouring cells. `FILTER` extracts rows meeting a condition, `SORT` puts them in order, `UNIQUE` removes duplicates.'),
            C('=FILTRO(A2:C100; C2:C100>1000)          righe con importo oltre 1000
=ORDINA(UNICI(B2:B100))                  clienti senza doppioni, in ordine
=SE.ERRORE(CERCA.X(E2;A:A;B:B);"—")      ricerca con valore di riserva
=SOMMA.PIÙ.SE(C:C;B:B;"Rossi";D:D;">="&DATA(2026;1;1))', 'excel'),
            P('`SE.ERRORE` sostituisce un errore (`#N/D`, `#DIV/0!`) con un valore scelto; `SOMMA.PIÙ.SE` somma con più condizioni. Nelle versioni inglesi le funzioni si chiamano `FILTER`, `SORT`, `UNIQUE`, `IFERROR`, `SUMIFS` e il separatore è la virgola.', '`IFERROR` replaces an error (`#N/A`, `#DIV/0!`) with a chosen value; `SUMIFS` sums with several conditions. In Italian versions the functions are `FILTRO`, `ORDINA`, `UNICI`, `SE.ERRORE`, `SOMMA.PIÙ.SE` and the separator is the semicolon.'),
        ], [
            Q('dy1', L('Che cosa fa `UNICI` (UNIQUE)?', 'What does `UNIQUE` do?'), [L('Toglie i doppioni', 'Removes duplicates'), L('Conta le celle', 'Counts cells'), L('Ordina', 'Sorts'), L('Somma', 'Sums')], 0, L('Spesso insieme a ORDINA.', 'Often with SORT.')),
            Q('dy2', L('Che cosa fa `SE.ERRORE` (IFERROR)?', 'What does `IFERROR` do?'), [L('Sostituisce un errore con un valore', 'Replaces an error with a value'), L('Crea un errore', 'Creates an error'), L('Cancella la riga', 'Deletes the row'), L('Colora la cella', 'Colours the cell')], 0, L('Niente #N/D nei report.', 'No #N/A in reports.')),
            Q('dy3', L('Che cosa significa che una formula si “espande”?', 'What does it mean that a formula “spills”?'), [L('I risultati riempiono le celle vicine', 'Results fill neighbouring cells'), L('Diventa più lenta', 'It gets slower'), L('Si copia in un altro file', 'It copies to another file'), L('Dà errore', 'It errors')], 0, L('È una matrice dinamica.', 'It is a dynamic array.')),
        ], task('excel', L('Scrivi una formula che filtra `A2:C50` tenendo le righe dove `C2:C50` è maggiore di `100` (in italiano o in inglese).', 'Write a formula filtering `A2:C50` keeping rows where `C2:C50` is greater than `100` (in Italian or English).'), '', [re('^=\s*(FILTRO|FILTER)\(\s*A2:C50\s*[;,]\s*C2:C50\s*>\s*100\s*\)', L('Il filtro è giusto', 'The filter is right'))], '', '=FILTRO(A2:C50;C2:C50>100)'), [
            dMatch(pMatch(), [['FILTRO / FILTER', L('Righe con una condizione', 'Rows meeting a condition')], ['ORDINA / SORT', L('Mette in ordine', 'Puts in order')], ['UNICI / UNIQUE', L('Senza doppioni', 'No duplicates')], ['SE.ERRORE / IFERROR', L('Valore di riserva', 'Fallback value')], ['SOMMA.PIÙ.SE / SUMIFS', L('Somma con più condizioni', 'Sum with several conditions')]], L('Le funzioni moderne.', 'Modern functions.')),
            dFlash(pFlash(), [[L('Una sola formula FILTRO può riempire molte celle', 'One FILTER formula can fill many cells'), true], [L('Nella versione italiana il separatore è la virgola', 'In the Italian version the separator is the comma'), false], [L('SE.ERRORE nasconde #N/D', 'IFERROR hides #N/A'), true], [L('UNICI somma i valori', 'UNIQUE sums values'), false]], L('Excel dinamico.', 'Dynamic Excel.')),
        ]),
        lesson('text-dates', L('Testi e date', 'Text and dates'), [
            P('Le funzioni di testo puliscono e uniscono: `TRIM`/`ANNULLA.SPAZI` toglie gli spazi in più, `PROPER`/`MAIUSC.INIZ` mette l’iniziale maiuscola, `LEFT`/`SINISTRA` prende i primi caratteri, `TEXTJOIN`/`TESTO.UNISCI` unisce un intervallo con un separatore. Anche l’operatore `&` unisce testi.', 'Text functions clean and join: `TRIM`/`ANNULLA.SPAZI` removes extra spaces, `PROPER`/`MAIUSC.INIZ` capitalises initials, `LEFT`/`SINISTRA` takes the first characters, `TEXTJOIN`/`TESTO.UNISCI` joins a range with a separator. The `&` operator joins text too.'),
            C('=A2&" "&B2                               nome e cognome
=MAIUSC.INIZ(ANNULLA.SPAZI(A2))          (inglese: =PROPER(TRIM(A2)))
=TESTO.UNISCI(", "; VERO; A2:A10)       (inglese: =TEXTJOIN(", ", TRUE, A2:A10))

=OGGI()                                  la data di oggi (inglese: =TODAY())
=ANNO(C2)                                l’anno di una data (inglese: =YEAR(C2))
=FINE.MESE(C2; 0)                        ultimo giorno del mese (inglese: =EOMONTH(C2, 0))
=GIORNI.LAVORATIVI.TOT(C2; D2)           giorni lavorativi tra due date (inglese: =NETWORKDAYS(C2, D2))', 'text'),
            P('Per Excel una data è un **numero**: i giorni passati dal 1° gennaio 1900. Per questo si può fare `=D2-C2` e ottenere i giorni tra due date, o `=C2+30` per spostarsi di un mese circa. `TEXT`/`TESTO` trasforma un numero o una data in testo formattato, per esempio `=TESTO(C2; "mmmm aaaa")`.', 'To Excel a date is a **number**: the days since 1 January 1900. That is why you can write `=D2-C2` to get the days between two dates, or `=C2+30` to move about a month ahead. `TEXT`/`TESTO` turns a number or date into formatted text, for example `=TEXT(C2, "mmmm yyyy")`.'),
        ], [
            Q('x1', L('Che cosa fa `ANNULLA.SPAZI` / `TRIM`?', 'What does `TRIM` / `ANNULLA.SPAZI` do?'), [L('Cancella la cella', 'Clears the cell'), L('Toglie gli spazi in più dal testo', 'Removes extra spaces from the text'), L('Taglia il testo a 10 caratteri', 'Cuts the text to 10 characters'), L('Mette il testo in maiuscolo', 'Puts the text in capitals')], 1, L('Utile sui dati copiati da altri sistemi.', 'Useful on data copied from other systems.')),
            Q('x2', L('Che cosa dà `=D2-C2` se le celle contengono due date?', 'What does `=D2-C2` give if the cells hold two dates?'), [L('Un errore', 'An error'), L('Il testo delle due date unite', 'The two dates joined as text'), L('Il numero di giorni tra le due date', 'The number of days between the two dates'), L('L’anno più recente', 'The latest year')], 2, L('Le date sono numeri.', 'Dates are numbers.')),
            Q('x3', L('Quale funzione unisce un intervallo di celle con un separatore?', 'Which function joins a range of cells with a separator?'), [L('`TEXTJOIN` / `TESTO.UNISCI`', '`TEXTJOIN` / `TESTO.UNISCI`'), L('`SUM` / `SOMMA`', '`SUM` / `SOMMA`'), L('`LEFT` / `SINISTRA`', '`LEFT` / `SINISTRA`'), L('`TODAY` / `OGGI`', '`TODAY` / `OGGI`')], 0, L('Il secondo argomento salta le celle vuote.', 'The second argument skips empty cells.')),
        ], task('excel', L('Scrivi una formula che unisca il nome in `A2` e il cognome in `B2` separati da uno spazio, togliendo gli spazi in più dal risultato con `ANNULLA.SPAZI` (o `TRIM`).', 'Write a formula joining the first name in `A2` and the surname in `B2` with a space, removing extra spaces from the result with `TRIM` (or `ANNULLA.SPAZI`).'), '', [re('^\s*=\s*(ANNULLA\.SPAZI|TRIM)\s*\(\s*A2\s*&\s*" "\s*&\s*B2\s*\)\s*$', L('Unisci e pulisci', 'You join and clean'))], '', '=ANNULLA.SPAZI(A2&" "&B2)'), [
            dMatch(pMatch(), [['TRIM', 'ANNULLA.SPAZI'], ['PROPER', 'MAIUSC.INIZ'], ['TEXTJOIN', 'TESTO.UNISCI'], ['TODAY', 'OGGI'], ['NETWORKDAYS', 'GIORNI.LAVORATIVI.TOT']], L('Inglese e italiano.', 'English and Italian.')),
            dFlash(pFlash(), [[L('Per Excel una data è un numero', 'To Excel a date is a number'), true], [L('L’operatore `&` unisce due testi', 'The `&` operator joins two texts'), true], [L('`OGGI()` resta fisso al giorno in cui l’hai scritto', '`TODAY()` stays fixed to the day you wrote it'), false], [L('`TESTO` trasforma una data in testo formattato', '`TEXT` turns a date into formatted text'), true]], L('Testi puliti, date che si contano.', 'Clean text, dates you can count.')),
        ]),
        lesson('format-validation', L('Formattazione condizionale e convalida', 'Conditional formatting and data validation'), [
            P('La **formattazione condizionale** (Home → Formattazione condizionale) colora le celle in base al loro valore: evidenzia gli importi sopra una soglia, i doppioni, le scadenze passate, o aggiunge barre e scale di colore. Con «Usa una formula» scrivi tu la regola, per esempio `=$E2<OGGI()` per colorare tutta la riga delle fatture scadute.', '**Conditional formatting** (Home → Conditional Formatting) colours cells based on their value: it highlights amounts over a threshold, duplicates, past deadlines, or adds data bars and colour scales. With “Use a formula” you write the rule yourself, for example `=$E2<TODAY()` to colour the whole row of overdue invoices.'),
            P('La **convalida dei dati** (Dati → Convalida dati) decide che cosa si può scrivere in una cella: un elenco a discesa di valori ammessi, numeri in un intervallo, date dopo un certo giorno. Un messaggio di input spiega che cosa inserire e un messaggio di errore blocca i valori sbagliati: i dati restano puliti alla fonte.', '**Data validation** (Data → Data Validation) decides what can be typed in a cell: a drop-down list of allowed values, numbers within a range, dates after a given day. An input message explains what to enter and an error alert blocks wrong values: data stays clean at the source.'),
            Tip('Nella regola con formula il dollaro conta: `=$E2` blocca la colonna E e lascia scorrere la riga, così la regola funziona su tutta la tabella.', 'In a formula rule the dollar matters: `=$E2` locks column E and lets the row move, so the rule works across the whole table.'),
        ], [
            Q('c1', L('A che cosa serve la formattazione condizionale?', 'What is conditional formatting for?'), [L('A bloccare le celle in modifica', 'Locking cells against editing'), L('A ordinare la tabella in automatico', 'Sorting the table automatically'), L('A cambiare il formato del file', 'Changing the file format'), L('A colorare le celle in base al loro valore', 'Colouring cells based on their value')], 3, L('Le anomalie saltano all’occhio.', 'Anomalies jump out.')),
            Q('c2', L('Come crei un elenco a discesa in una cella?', 'How do you create a drop-down list in a cell?'), [L('Con la convalida dei dati, tipo Elenco', 'With data validation, List type'), L('Con una tabella pivot', 'With a pivot table'), L('Con la formattazione condizionale', 'With conditional formatting'), L('Unendo più celle', 'By merging several cells')], 0, L('Dati → Convalida dati → Elenco.', 'Data → Data Validation → List.')),
            Q('c3', L('Nella regola `=$E2<OGGI()`, perché il dollaro solo davanti alla E?', 'In the rule `=$E2<TODAY()`, why the dollar only before the E?'), [L('Per rendere la regola più veloce', 'To make the rule faster'), L('Per indicare una valuta', 'To indicate a currency'), L('Per bloccare la colonna e lasciar scorrere la riga', 'To lock the column and let the row move'), L('Per bloccare sia riga sia colonna', 'To lock both row and column')], 2, L('Così ogni riga controlla la sua data.', 'So each row checks its own date.')),
        ], task('text', L('Descrivi le due regole per una colonna «Stato» degli ordini: una riga `Convalida:` con l’elenco dei valori ammessi e una riga `Formattazione:` che dice quale stato colorare e di che colore.', 'Describe the two rules for an orders “Status” column: a `Validation:` line with the list of allowed values and a `Formatting:` line saying which status to colour and in which colour.'), "Convalida: \nFormattazione: ", [re('^(Convalida|Validation):\s*.*(elenco|list|,)', L('Un elenco di valori ammessi', 'A list of allowed values')), re('^(Formattazione|Formatting):\s*.*(ross|verd|giall|arancio|blu|red|green|yellow|orange|blue|colou?r)', L('Uno stato con il suo colore', 'A status with its colour'))], '', "Convalida: elenco con nuovo, pagato, spedito, annullato\nFormattazione: colora di rosso le righe con stato annullato"), [
            dMatch(pMatch(), [[L('Formattazione condizionale', 'Conditional formatting'), L('Colori in base ai valori', 'Colours based on values')], [L('Convalida dati', 'Data validation'), L('Che cosa si può scrivere', 'What may be typed')], [L('Elenco a discesa', 'Drop-down list'), L('Valori ammessi', 'Allowed values')], [L('Barre dei dati', 'Data bars'), L('Grandezza a colpo d’occhio', 'Size at a glance')], ['=$E2<OGGI()', L('Riga scaduta', 'Overdue row')]], L('Dati chiari e puliti.', 'Clear, clean data.')),
            dFlash(pFlash(), [[L('La convalida può bloccare un valore sbagliato', 'Validation can block a wrong value'), true], [L('La formattazione condizionale cambia i valori delle celle', 'Conditional formatting changes the cells’ values'), false], [L('Una regola può usare una formula', 'A rule can use a formula'), true], [L('L’elenco a discesa si crea con le celle unite', 'The drop-down list is made with merged cells'), false]], L('Il colore aiuta, la convalida protegge.', 'Colour helps, validation protects.')),
        ]),
        lesson('let-lambda', L('LET e LAMBDA', 'LET and LAMBDA'), [
            P('`LET` dà un **nome** a un calcolo dentro la formula: lo scrivi una volta e lo riusi, così la formula è più leggibile e più veloce. `LAMBDA` va oltre: crea una **funzione tua**, che salvi con un nome in Formule → Gestione nomi e poi usi come `SOMMA`. Entrambe hanno lo stesso nome in italiano e in inglese.', '`LET` gives a **name** to a calculation inside the formula: you write it once and reuse it, so the formula is more readable and faster. `LAMBDA` goes further: it creates **your own function**, which you save with a name in Formulas → Name Manager and then use like `SUM`. Both have the same name in Italian and English.'),
            C('=LET(netto; B2*C2; iva; netto*0,22; netto+iva)
=LET(netto, B2*C2, iva, netto*0.22, netto+iva)            (inglese)

nome definito  CONIVA  =LAMBDA(prezzo; prezzo*1,22)
uso            =CONIVA(B2)', 'text'),
            P('In `LET` gli argomenti vanno a coppie (nome, valore) e l’ultimo è il risultato. Una `LAMBDA` salvata con un nome vale in tutta la cartella di lavoro: utile per calcoli aziendali ripetuti, come l’IVA o una commissione. Le funzioni `MAP`, `REDUCE` e `BYROW` usano una `LAMBDA` per lavorare riga per riga su un intervallo.', 'In `LET` arguments come in pairs (name, value) and the last one is the result. A `LAMBDA` saved with a name works across the whole workbook: useful for repeated business calculations, such as VAT or a commission. The `MAP`, `REDUCE` and `BYROW` functions use a `LAMBDA` to work row by row on a range.'),
        ], [
            Q('a1', L('Che cosa fa `LET`?', 'What does `LET` do?'), [L('Blocca la cella per gli altri utenti', 'Locks the cell for other users'), L('Crea una tabella pivot', 'Creates a pivot table'), L('Unisce più fogli di lavoro', 'Merges several worksheets'), L('Dà un nome a un calcolo dentro la formula', 'Gives a name to a calculation inside the formula')], 3, L('Lo calcoli una volta e lo riusi.', 'You compute it once and reuse it.')),
            Q('a2', L('In `=LET(x; A1*2; x+1)` qual è il risultato?', 'In `=LET(x, A1*2, x+1)` what is the result?'), [L('A1 per 2', 'A1 times 2'), L('A1 per 2, più 1', 'A1 times 2, plus 1'), L('Il testo «x»', 'The text “x”'), L('Un errore', 'An error')], 1, L('L’ultimo argomento è il risultato.', 'The last argument is the result.')),
            Q('a3', L('Dove salvi una `LAMBDA` per usarla come funzione?', 'Where do you save a `LAMBDA` to use it as a function?'), [L('In Gestione nomi, con un nome', 'In the Name Manager, with a name'), L('In una macro VBA', 'In a VBA macro'), L('Nelle opzioni di stampa', 'In the print options'), L('Non si può salvare', 'It cannot be saved')], 0, L('Poi la chiami come `=CONIVA(B2)`.', 'Then you call it like `=CONIVA(B2)`.')),
        ], task('excel', L('Scrivi una formula `LET` che chiami `totale` il prodotto di `B2` per `C2` e restituisca `totale` scontato del 10% (`totale*0,9` o `totale*0.9`).', 'Write a `LET` formula that names `totale` the product of `B2` and `C2` and returns `totale` with a 10% discount (`totale*0.9` or `totale*0,9`).'), '', [re('^\s*=\s*LET\s*\(\s*totale\s*[;,]\s*(B2\s*\*\s*C2|C2\s*\*\s*B2)\s*[;,]\s*totale\s*\*\s*0[,.]9\s*\)\s*$', L('LET con il nome totale', 'LET with the name totale'))], '', '=LET(totale; B2*C2; totale*0,9)'), [
            dOrder(pSort(), ['=LET(', 'netto; B2*C2;', 'iva; netto*0,22;', 'netto+iva)'], L('Nome e valore, nome e valore, poi il risultato.', 'Name and value, name and value, then the result.')),
            dMatch(pMatch(), [['LET', L('Nomi dentro la formula', 'Names inside the formula')], ['LAMBDA', L('Una funzione tua', 'Your own function')], [L('Gestione nomi', 'Name Manager'), L('Dove salvi la LAMBDA', 'Where you save the LAMBDA')], ['BYROW', L('Calcola riga per riga', 'Computes row by row')]], L('Formule più leggibili.', 'More readable formulas.')),
        ]),
        lesson('modern', L('Novità: regex, GROUPBY, Python e Copilot', 'What is new: regex, GROUPBY, Python and Copilot'), [
            P('Microsoft 365 aggiunge spesso funzioni nuove. `REGEXTEST`, `REGEXEXTRACT` e `REGEXREPLACE` usano le **espressioni regolari** per controllare, estrarre e sostituire testo (hanno lo stesso nome in italiano). **`GROUPBY`** (in italiano `RAGGRUPPA.PER`) fa un riepilogo come una piccola pivot, ma con una formula che si aggiorna da sola.', 'Microsoft 365 often adds new functions. `REGEXTEST`, `REGEXEXTRACT` and `REGEXREPLACE` use **regular expressions** to check, extract and replace text (they keep the same name in Italian). **`GROUPBY`** (Italian `RAGGRUPPA.PER`) builds a summary like a small pivot, but with a formula that updates by itself.'),
            C('=REGEXTEST(A2; "^[A-Z]{2}\d{5}$")          il codice è di 2 lettere e 5 cifre?
=REGEXEXTRACT(B2; "\d+")                     il primo numero nel testo
=RAGGRUPPA.PER(A2:A100; C2:C100; SOMMA)       totale per categoria
=GROUPBY(A2:A100, C2:C100, SUM)               (inglese)', 'text'),
            P('Con **Python in Excel** (`=PY(`) scrivi codice Python nella cella, con pandas e grafici, eseguito nel cloud di Microsoft. **Copilot** aiuta a scrivere formule, evidenziare tendenze e creare grafici descrivendo a parole che cosa ti serve: utile, ma controlla sempre le formule che propone. Queste funzioni richiedono Microsoft 365, non le versioni a licenza singola.', 'With **Python in Excel** (`=PY(`) you write Python code in a cell, with pandas and charts, run in Microsoft’s cloud. **Copilot** helps write formulas, highlight trends and create charts when you describe in words what you need: useful, but always check the formulas it suggests. These features require Microsoft 365, not the one-off licence versions.'),
        ], [
            Q('g1', L('Che cosa restituisce `REGEXTEST`?', 'What does `REGEXTEST` return?'), [L('Il testo trovato', 'The text found'), L('La posizione del testo', 'The position of the text'), L('VERO o FALSO, se il modello corrisponde', 'TRUE or FALSE, whether the pattern matches'), L('Il numero di parole', 'The number of words')], 2, L('`REGEXEXTRACT` restituisce il testo.', '`REGEXEXTRACT` returns the text.')),
            Q('g2', L('Qual è il vantaggio di `GROUPBY` rispetto a una tabella pivot?', 'What is the advantage of `GROUPBY` over a pivot table?'), [L('Disegna grafici in 3D', 'It draws 3D charts'), L('Funziona anche in Excel 2010', 'It also works in Excel 2010'), L('Non ha bisogno di dati', 'It needs no data'), L('È una formula che si aggiorna da sola', 'It is a formula that updates by itself')], 3, L('La pivot va aggiornata a mano.', 'A pivot has to be refreshed by hand.')),
            Q('g3', L('Che cosa conviene fare con le formule proposte da Copilot?', 'What should you do with the formulas Copilot suggests?'), [L('Controllarle prima di fidarti', 'Check them before trusting them'), L('Usarle senza guardarle', 'Use them without looking'), L('Stamparle e cancellarle', 'Print and delete them'), L('Trasformarle in macro', 'Turn them into macros')], 0, L('L’IA può sbagliare riferimenti e criteri.', 'AI can get references and criteria wrong.')),
        ], task('excel', L('Scrivi una formula che controlli con `REGEXTEST` se l’email in `A2` contiene una chiocciola seguita da un punto più avanti, con il modello `"@.+\."`.', 'Write a formula checking with `REGEXTEST` whether the email in `A2` contains an at sign followed later by a dot, with the pattern `"@.+\."`.'), '', [re('^\s*=\s*REGEXTEST\s*\(\s*A2\s*[;,]\s*"@\.\+\\\\\."\s*\)\s*$', L('Il controllo con la regex', 'The regex check'))], '', '=REGEXTEST(A2; "@.+\.")'), [
            dMatch(pMatch(), [['REGEXTEST', L('Il modello corrisponde?', 'Does the pattern match?')], ['REGEXEXTRACT', L('Estrae il testo', 'Extracts the text')], ['REGEXREPLACE', L('Sostituisce il testo', 'Replaces the text')], ['GROUPBY / RAGGRUPPA.PER', L('Riepilogo con una formula', 'Summary with a formula')], ['=PY(', L('Python nella cella', 'Python in the cell')]], L('Excel moderno.', 'Modern Excel.')),
            dFlash(pFlash(), [[L('Le funzioni REGEX usano le espressioni regolari', 'The REGEX functions use regular expressions'), true], [L('Python in Excel gira sul tuo computer senza internet', 'Python in Excel runs on your computer without internet'), false], [L('Copilot può proporre formule da controllare', 'Copilot can suggest formulas to check'), true], [L('`GROUPBY` si aggiorna quando cambiano i dati', '`GROUPBY` updates when the data changes'), true]], L('Nuovi strumenti, stesso buon senso.', 'New tools, same common sense.')),
        ]),
    ],
];
